const fs=require('fs'),assert=require('assert/strict'),crypto=require('crypto');const {load}=require('./load-ts.cjs');const posts=load('lib/dailyPosts20261102.ts').DAILY_POSTS_20261102;const all=load('lib/blogPosts.ts').BLOG_POSTS;const base='https://www.11plusexampapers.com';
assert.equal(posts.length,5);assert.equal(new Set(all.map(p=>p.slug)).size,all.length);let questions=0;
for(const p of posts){const html=fs.readFileSync('.next/server/app/blog/'+p.slug+'.html','utf8');assert(html.includes('rel="canonical" href="'+base+'/blog/'+p.slug+'"'));assert(!html.includes('content="noindex'));assert(html.includes('property="og:image" content="'+base+p.imageUrl+'"'));assert(html.includes('"image":["'+base+p.imageUrl+'"]'));const hub=fs.readFileSync('.next/server/app/subjects/'+p.subject+'.html','utf8');assert(hub.includes('/blog/'+p.slug));assert(p.content.some(b=>b.text?.includes('/subjects/'+p.subject+')')));for(const b of p.content){for(const target of (b.text||'').matchAll(/\]\((\/[^)]+)\)/g)){const path=target[1];assert(fs.existsSync('.next/server/app'+path+'.html')||fs.existsSync('.next/server/app'+path+'/index.html')||Object.keys(require('../.next/server/app-paths-manifest.json')).some(k=>k===path+'/page'),'Missing '+path)}}questions+=p.content.filter(b=>b.type==='question').length;assert.equal((html.match(/<details[ >]/g)||[]).length,p.content.filter(b=>b.type==='question').length);assert(!html.includes('<details open'));}
assert.equal(questions,35);
// Independently reviewed grammar keys: constrain ambiguous meanings and accept model alternatives.
const keys=[['beside','beneath the blue cushion','at','for','B','by'],['because','so','Although','or','If the mist clears'],['Determiner: those. Adjective: fragile. Noun: ornaments.','an hour; a useful information board','These','many','her','Every player brought a water bottle.','a; The'],['might','B: copy','Can Noah mend the kite?','Permission'],['tallest','wider; widest','thinner','busiest','This solution is better than mine.','more colourful']];
for(let i=0;i<posts.length;i++){const qs=posts[i].content.filter(b=>b.type==='question');assert.equal(qs.length,7);keys[i].forEach((key,j)=>assert.equal(qs[j].answer,key));for(const q of qs){assert(q.explanation.length>40);assert(q.answer.trim())}}
assert(posts[0].content.some(b=>b.type==='question'&&b.answer.startsWith('No. For example')));
assert(posts[1].content.some(b=>b.explanation?.includes('also correct')));
assert(posts[3].content.some(b=>b.explanation?.includes('does not encode a fixed numerical probability')));
assert(posts[4].content.some(b=>b.explanation?.includes('missing comparison matters')));
const inv=fs.readFileSync('docs/releases/url-inventory-2026-11-02.txt','utf8').trim().split('\n');const sitemap=fs.readFileSync('.next/server/app/sitemap.xml.body','utf8');for(const u of [...inv,...posts.map(p=>base+'/blog/'+p.slug)])assert(sitemap.includes('<loc>'+u+'</loc>'));assert.equal((sitemap.match(/<loc>/g)||[]).length,251);assert(!/\/(quiz|lesson-preview|test|api)[/<]/.test(sitemap));
for(const x of JSON.parse(fs.readFileSync('docs/artwork/blog-artwork-2026-11-02.json')).items){for(const a of [x.asset,x.thumbnail])assert.equal(crypto.createHash('sha256').update(fs.readFileSync(a.path)).digest('hex'),a.sha256)}console.log('PASS five pages;35 original questions;grammar key checks;canonical/social/schema;reciprocal hub/internal targets;251 sitemap URLs;10 artwork hashes');
